import * as os from 'os'
import ciInfo from 'ci-info'
import type { PostHog } from 'posthog-node'
import { crypto } from '../../crypto'
import type { Telemetry, TelemetryProperties, TelemetryContext } from '../types'
import { describeError } from './util'
import { detectCodingAgent, detectIde } from './detect-agent'

// Set by a caller (e.g. a mass app-conversion script running init/transform/build in a loop)
// to tag every telemetry event from that run as automated-conversion volume, so it can be
// filtered out of organic usage metrics.
function detectFromConversion(env: NodeJS.ProcessEnv): boolean {
    return env['FLUENT_CONVERSION_EFFORT'] === '1'
}

export type PostHogNodeClientOptions = {
    apiKey: string
    host: string
    sdkVersion?: string | undefined
    clientName?: 'CLI' | 'IDE' | (string & {}) | undefined
    // Instance host the command targets (e.g. `myinstance.service-now.com`) — the host portion
    // only, never the full URL. Supplied by the consumer; unset when no instance is involved.
    hostname?: string | undefined
    codingAgent?: string | undefined
}

export class PostHogNodeClient implements Telemetry {
    private posthog?: PostHog
    private initPromise?: Promise<PostHog>
    private readonly context: TelemetryContext
    private distinctIdPromise?: Promise<string>
    private readonly pending = new Set<Promise<void>>()
    private readonly options: PostHogNodeClientOptions

    constructor(options: PostHogNodeClientOptions) {
        this.options = options
        this.context = this.buildContext(options)
        this.ensureInitialized().catch(() => {})
    }

    capture(event: string, properties?: TelemetryProperties): void {
        // Tracked in `pending` so flush()/shutdown() await the full capture chain (init +
        // distinctId + enqueue) before flushing — otherwise a capture() immediately followed by
        // flush() and process exit could drop the event.
        const send = Promise.all([this.ensureInitialized(), this.getDistinctId()])
            .then(([posthog, distinctId]) => {
                posthog.capture({
                    distinctId,
                    event,
                    properties: {
                        ...this.context,
                        ...properties,
                    },
                })
            })
            .catch(() => {})
        this.pending.add(send)
        void send.finally(() => this.pending.delete(send))
    }

    captureError(event: string, error: unknown, properties?: TelemetryProperties): void {
        const { category, fingerprint, message } = describeError(error)
        this.capture(event, {
            success: false,
            error_category: category,
            error_fingerprint: fingerprint,
            error_message: message,
            ...properties,
        })
    }

    async flush(): Promise<void> {
        await Promise.all(this.pending)
        try {
            const posthog = await this.ensureInitialized()
            await posthog.flush()
        } catch {
            // Telemetry must never fail a build — callers often await this from a `finally`
            // block, where a rejection would override a successful try block's result.
        }
    }

    async shutdown(): Promise<void> {
        await Promise.all(this.pending)
        try {
            const posthog = await this.ensureInitialized()
            await posthog.shutdown()
        } catch {
            // Telemetry must never fail a build — callers often await this from a `finally`
            // block, where a rejection would override a successful try block's result.
        }
    }

    private async ensureInitialized(): Promise<PostHog> {
        if (this.posthog) {
            return this.posthog
        }

        if (this.initPromise !== undefined) {
            return this.initPromise
        }

        this.initPromise = this.loadPostHog()
        this.posthog = await this.initPromise
        return this.posthog
    }

    private async loadPostHog(): Promise<PostHog> {
        const { PostHog } = await import('posthog-node')
        return new PostHog(this.options.apiKey, {
            host: this.options.host,
            flushInterval: 0,
            flushAt: 10,
            requestTimeout: 3000,
            featureFlagsPollingInterval: 0,
            disableGeoip: true,
        })
    }

    private buildContext(options: PostHogNodeClientOptions): TelemetryContext {
        const agentData: { codingAgent?: string; ide?: string } = {}
        const codingAgent = options.codingAgent ?? detectCodingAgent(process.env)
        if (codingAgent) {
            agentData.codingAgent = codingAgent
        }
        const ide = detectIde(process.env, process.platform)
        if (ide) {
            agentData.ide = ide
        }

        const context: TelemetryContext = {
            sdkVersion: options.sdkVersion ?? 'unknown',
            clientName: options.clientName ?? 'CLI',
            nodeVersion: process.version,
            os: os.type(),
            isCI: ciInfo.isCI,
        }

        if (ciInfo.name) {
            context.ciName = ciInfo.name
        }

        if (options.hostname) {
            context.hostname = options.hostname
        }

        if (agentData.codingAgent) {
            context.codingAgent = agentData.codingAgent
        }
        if (agentData.ide) {
            context.ide = agentData.ide
        }

        if (detectFromConversion(process.env)) {
            context.fromConversion = true
        }

        return context
    }

    private getDistinctId(): Promise<string> {
        if (!this.distinctIdPromise) {
            this.distinctIdPromise = this.resolveAnonymousId()
        }
        return this.distinctIdPromise
    }

    // Derived from a SHA-256 of `username:hostname` rather than a persisted random id: stable
    // across runs and reinstalls with no local state to store, and hashed so the raw
    // username/hostname is never transmitted.
    private async resolveAnonymousId(): Promise<string> {
        let username = 'unknown'
        try {
            username = os.userInfo().username || 'unknown'
        } catch {
            // os.userInfo() throws when the running uid has no passwd entry (e.g. some containers)
        }
        const bytes = new TextEncoder().encode(`${username}:${os.hostname()}`)
        const digest = await crypto.subtle.digest('SHA-256', bytes)
        return Buffer.from(digest).toString('hex')
    }
}
